from abc import ABC, abstractmethod

class ValidationRule(ABC):
    @abstractmethod
    def check(self, sentence: str) -> str | None:
        """通过返回 None;不通过返回一条错误信息"""

class CapitalStartRule(ValidationRule):
    def check(self, sentence: str) -> str | None:
        if not sentence or not sentence[0].isupper():
            return "must start with a capital letter"
        return None

class SentenceValidator:
    def __init__(self, rules: list[ValidationRule]):
        self._rules = rules            # 注入规则列表(组合)

    def validate(self, sentence: str) -> "ValidationResult":
        errors = []
        for rule in self._rules:
            err = rule.check(sentence)
            if err is not None:        # collect-all
                errors.append(err)
        return ValidationResult(is_valid=not errors, errors=errors)
